import { FormEvent, Suspense, useCallback, useEffect, useState } from 'react'
import { ago, bytes } from './utils'

type Report = {
  collected_at: string
  policy_version?: number
  system: { hostname: string; distribution: string; kernel_version: string; uptime_seconds: number; agent_version: string }
  cpu: { usage_percent: number; core_usage_percent: number[]; load_1: number }
  memory: { total_bytes: number; used_bytes: number; available_bytes: number; usage_percent: number; memory_pressure_avg10?: number }
  disks: { device:string; mountpoint: string; filesystem: string; usage_percent: number; total_bytes:number; used_bytes:number; free_bytes:number; inodes_usage_percent?:number; read_only: boolean }[]
  interfaces: {name:string;mtu:number;hardware_address:string;flags:string[];up:boolean}[]
  network: { name: string; rx_bytes: number; tx_bytes: number; rx_bytes_per_second:number; tx_bytes_per_second:number; rx_errors: number; tx_errors: number; rx_drops: number; tx_drops: number }[]
  disk_io: {device:string;read_bytes:number;write_bytes:number;read_count:number;write_count:number}[]
  processes: { pid: number; name: string; cpu_percent: number; memory_bytes: number; threads:number; status: string; uptime_seconds:number }[]
  services: { name: string; active_state: string; sub_state: string; main_pid: number; last_result?: string; restart_count?: number; since?: string }[]
  alerts: { metric: string; value: number; threshold: number; message: string }[]
  recommendations: {type:string;severity:string;target:string;message:string}[]
  warnings: string[]
}
type Host = { id: string; hostname: string; distribution: string; kernel_version: string; agent_version: string; policy_version: number; last_seen: string; online: boolean; cpu_usage_percent: number; memory_usage_percent: number; open_incidents: number; health_score: number; health_components?: Record<string,number>; report?: Report }
type Incident = { id: number; host_id: string; type: string; severity: string; description: string; status: string; first_seen: string; last_seen: string }
type Recovery = { id: number; host_id: string; policy: string; service: string; started_at: string; outcome: string; verified: boolean; error: string }
type Policy = { id: string; name: string; action_type: string; service: string; failure_for: string; max_attempts: number; cooldown: string; verification_timeout: string; require_approval: boolean; enabled: boolean; host_ids: string[] }
type Overview = { total_hosts: number; online_hosts: number; healthy_hosts: number; critical_hosts: number; active_incidents: number; successful_recoveries: number }
type HistorySeries = {name:string;labels?:Record<string,string>;points:{timestamp:number;value:number}[]}
type Group = { id: string; name: string; host_ids: string[]; host_count: number }
type Page = 'overview' | 'hosts' | 'cpu' | 'memory' | 'disk' | 'processes' | 'services' | 'groups' | 'incidents' | 'incident-history' | 'recoveries' | 'policies' | 'notifications' | 'reports' | 'settings'

async function api<T>(path: string, init?: RequestInit): Promise<T> {
  const token=sessionStorage.getItem('hostsentry-session')
  const response = await fetch(path, { ...init, headers: { 'Content-Type': 'application/json', ...(token?{Authorization:`Bearer ${token}`} : {}), ...init?.headers } })
  if (!response.ok) {
    const body = await response.json().catch(() => null)
    if(response.status===401){sessionStorage.removeItem('hostsentry-session');window.dispatchEvent(new Event('hostsentry-session-expired'))}
    throw new Error(body?.error?.message ?? `Request failed (${response.status})`)
  }
  if (response.status === 204) return undefined as T
  return response.json()
}
async function fetchAllHosts(groupID = '', includeReport = false): Promise<Host[]> {
  const all: Host[] = []
  const pageSize = includeReport ? 50 : 200
  for (let offset = 0; offset <= 100_000; offset += pageSize) {
    const groupFilter = groupID ? '&group_id='+encodeURIComponent(groupID) : ''
    const reportFilter = includeReport ? '&include_report=true' : ''
    const page = await api<{items:Host[]}>('/api/v1/hosts?limit='+pageSize+'&offset='+offset+groupFilter+reportFilter)
    all.push(...page.items)
    if (page.items.length < 200) return all
  }
  throw new Error('Host list exceeds the supported pagination limit')
}
export default function App() {
  const [token,setToken]=useState(()=>sessionStorage.getItem('hostsentry-session'))
  const [role,setRole]=useState('viewer')
  const [page, setPage] = useState<Page>('overview')
  const [hosts, setHosts] = useState<Host[]>([])
  const [incidents, setIncidents] = useState<Incident[]>([])
  const [recoveries, setRecoveries] = useState<Recovery[]>([])
  const [policies, setPolicies] = useState<Policy[]>([])
  const [groups, setGroups] = useState<Group[]>([])
  const [groupHosts, setGroupHosts] = useState<Host[] | null>(null)
  const [viewGroup, setViewGroup] = useState<Group | null>(null)
  const [summary, setSummary] = useState<Overview>({total_hosts:0,online_hosts:0,healthy_hosts:0,critical_hosts:0,active_incidents:0,successful_recoveries:0})
  const [recoveryEnabled, setRecoveryEnabled] = useState(false)
  const [recoveryDryRun, setRecoveryDryRun] = useState(true)
  const [selected, setSelected] = useState<Host | null>(null)
  const [error, setError] = useState('')
  useEffect(()=>{const expired=()=>{setToken(null);setRole('viewer')};window.addEventListener('hostsentry-session-expired',expired);return()=>window.removeEventListener('hostsentry-session-expired',expired)},[])
  useEffect(()=>{if(!token)return;void api<{role:string}>('/api/v1/auth/me').then(me=>setRole(me.role)).catch(()=>undefined)},[token])
  const refresh = useCallback(async () => {
    try {
      const [h, i, r, p, s, g] = await Promise.all([
        fetchAllHosts(),
        api<{ items: Incident[] }>('/api/v1/incidents?limit=100'),
        api<{ items: Recovery[] }>('/api/v1/recoveries?limit=100'),
        api<{ items: Policy[]; recovery_enabled: boolean; dry_run: boolean }>('/api/v1/policies'),
        api<Overview>('/api/v1/overview'),
        api<{items:Group[]}>('/api/v1/groups'),
      ])
      setHosts(h); setIncidents(i.items); setRecoveries(r.items); setPolicies(p.items); setRecoveryEnabled(p.recovery_enabled); setRecoveryDryRun(p.dry_run); setSummary(s); setGroups(g.items); setError('')
    } catch (e) { setError(e instanceof Error ? e.message : 'Could not load fleet data') }
  }, [])
  useEffect(() => { if(!token)return;void refresh(); const timer = window.setInterval(() => void refresh(), 30_000); return () => window.clearInterval(timer) }, [refresh,token])
  const openHost = async (id: string) => {
    try { setSelected(await api<Host>(`/api/v1/hosts/${encodeURIComponent(id)}`)); setPage('hosts') }
    catch (e) { setError(e instanceof Error ? e.message : 'Could not load host') }
  }
  const openGroup = async (group: Group) => {
    try { setGroupHosts(await fetchAllHosts(group.id)); setViewGroup(group); setSelected(null); setPage('hosts') }
    catch (e) { setError(e instanceof Error ? e.message : 'Could not load group hosts') }
  }
  const clearGroup = () => { setGroupHosts(null); setViewGroup(null) }
  const changeIncident = async (id: number, status: string) => {
    try { await api(`/api/v1/incidents/${id}`, { method: 'PATCH', body: JSON.stringify({ status }) }); await refresh() }
    catch (e) { setError(e instanceof Error ? e.message : 'Could not update incident') }
  }
  const online = summary.online_hosts
  const active = summary.active_incidents
  const healthy = summary.healthy_hosts
  const navigation: [Page,string][] = [
    ['overview','Overview'],['hosts','All hosts'],['cpu','CPU monitoring'],['memory','Memory monitoring'],['disk','Disk monitoring'],
    ['processes','Process monitoring'],['services','Service monitoring'],['groups','Host groups'],['incidents','Active incidents'],
    ['incident-history','Incident history'],['policies','Recovery policies'],['recoveries','Recovery history'],['notifications','Notifications'],
    ['reports','Reports'],['settings','Settings'],
  ]

  if(!token)return <LoginView onLogin={(sessionToken,userRole)=>{sessionStorage.setItem('hostsentry-session',sessionToken);setRole(userRole);setToken(sessionToken)}} />
  return <div className="shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark">H</div><div><strong>HostSentry</strong><span>FLEET OPERATIONS</span></div></div>
      <div className="nav-label">MONITORING</div>
      <nav>{navigation.map(([key,label]) =>
        <button key={key} className={page===key?'nav-item selected':'nav-item'} onClick={() => { setPage(key); setSelected(null); if(key==='hosts')clearGroup() }}><span className="nav-dot" />{label}{key==='incidents' && active>0 && <b className="nav-count">{active}</b>}</button>)}</nav>
      <div className="sidebar-bottom"><span className="live-dot"/> {error?'API unavailable':'API connected'} <small>v0.1 · agent snapshots</small><button className="text-button" onClick={()=>{void api('/api/v1/auth/logout',{method:'POST'}).catch(()=>undefined).finally(()=>{sessionStorage.removeItem('hostsentry-session');setToken(null)})}}>Sign out</button></div>
    </aside>
    <main className="main">
      <header className="topbar"><div><span className="eyebrow">FLEET / {selected && page==='hosts' ? selected.hostname : page.toUpperCase()}</span><h1>{selected && page==='hosts' ? selected.hostname : ({overview:'Fleet overview',hosts:viewGroup?.name??'All hosts',cpu:'CPU monitoring',memory:'Memory monitoring',disk:'Disk monitoring',processes:'Process monitoring',services:'Service monitoring',groups:'Host groups',incidents:'Active incidents','incident-history':'Incident history',recoveries:'Recovery history',policies:'Recovery policies',notifications:'Notifications',reports:'Reports',settings:'Settings'}[page])}</h1></div><div className="top-actions"><span className="refresh-label">Refreshes every 30 seconds</span><button className="refresh" onClick={() => void refresh()}>↻ <span>Refresh</span></button></div></header>
      {error && <div className="error-banner"><strong>Data unavailable</strong><span>{error}</span></div>}
      {page==='overview' && <>
        <section className="cards">
          <Metric title="Total hosts" value={summary.total_hosts} note="Registered in fleet" tone="blue" />
          <Metric title="Online" value={online} note={`${summary.total_hosts-online} offline`} tone="green" />
          <Metric title="Healthy" value={healthy} note="Online with no open incidents" tone="teal" />
          <Metric title="Active incidents" value={active} note="Needs attention" tone={active?'red':'green'} />
          <Metric title="Successful recoveries" value={summary.successful_recoveries} note="Verified from agent reports" tone="purple" />
        </section>
        <section className="panel"><div className="panel-heading"><div><h2>Host health</h2><p>Latest agent reports</p></div><button className="text-button" onClick={()=>setPage('hosts')}>View all hosts →</button></div><HostTable hosts={hosts.slice(0,8)} onOpen={openHost}/></section>
        <div className="two-col"><section className="panel"><div className="panel-heading"><div><h2>Recent incidents</h2><p>From resource thresholds and service state</p></div><button className="text-button" onClick={()=>setPage('incidents')}>View all →</button></div><IncidentList incidents={incidents.filter(i=>i.status!=='resolved').slice(0,5)} onChange={changeIncident} canChange={role!=='viewer'}/></section><section className="panel"><div className="panel-heading"><div><h2>Recent recoveries</h2><p>Agent-reported actions</p></div><button className="text-button" onClick={()=>setPage('recoveries')}>History →</button></div><RecoveryList items={recoveries.slice(0,5)}/></section></div>
      </>}
      {page==='hosts' && (selected ? <Suspense fallback={<section className="panel"><Empty text="Loading host charts…"/></section>}><HostDetails host={selected} onBack={()=>setSelected(null)} /></Suspense> : <section className="panel"><div className="panel-heading"><div><h2>{viewGroup?.name??'All hosts'}</h2><p>Showing {(groupHosts??hosts).length} registered agents</p>{viewGroup&&<button className="text-button" onClick={clearGroup}>← Clear group filter</button>}</div></div><HostTable hosts={groupHosts??hosts} onOpen={openHost}/></section>)}
      {(['cpu','memory','disk','processes','services'] as const).includes(page as 'cpu'|'memory'|'disk'|'processes'|'services') && <FleetMetricsView section={page as 'cpu'|'memory'|'disk'|'processes'|'services'} onOpenHost={openHost} />}
      {page==='groups' && <GroupsView groups={groups} hosts={hosts} refresh={refresh} onOpen={openGroup} readOnly={role!=='admin'} />}
      {page==='incidents' && <IncidentPage status="active" onChange={changeIncident} canChange={role!=='viewer'} />}
      {page==='incident-history' && <IncidentPage status="resolved" onChange={changeIncident} canChange={false} />}
      {page==='recoveries' && <section className="panel"><div className="panel-heading"><div><h2>Recovery history</h2><p>Actions include their verification outcome</p></div></div><RecoveryList items={recoveries}/></section>}
      {page==='policies' && <PoliciesView policies={policies} hosts={hosts} recoveryEnabled={recoveryEnabled} dryRun={recoveryDryRun} refresh={refresh} readOnly={role!=='admin'} />}
      {page==='notifications' && <NotificationsView />}
      {page==='reports' && <ReportsView />}
      {page==='settings' && <SettingsView />}
      <footer>HostSentry · Data from connected agents · Last refresh {new Date().toLocaleTimeString()}</footer>
    </main>
  </div>
}

function Metric({title,value,note,tone}:{title:string;value:number;note:string;tone:string}){return <article className="metric"><div className="metric-top"><span>{title}</span><i className={`tone-${tone}`}/></div><strong>{value}</strong><small>{note}</small></article>}
function LoginView({onLogin}:{onLogin:(token:string,role:string)=>void}){
  const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  const submit=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();setBusy(true);setError('');try{const result=await api<{token:string;user:{role:string}}>('/api/v1/auth/login',{method:'POST',body:JSON.stringify({email,password})});onLogin(result.token,result.user.role)}catch(e){setError(e instanceof Error?e.message:'Sign in failed')}finally{setBusy(false)}}
  return <main className="login-shell"><form className="panel login-card" onSubmit={submit}><div className="brand"><div className="brand-mark">H</div><div><strong>HostSentry</strong><span>FLEET OPERATIONS</span></div></div><h1>Sign in</h1><p>Use your central HostSentry account.</p>{error&&<div className="error-banner">{error}</div>}<label>Email<input type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Password<input type="password" autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="refresh" disabled={busy}>{busy?'Signing in…':'Sign in'}</button></form></main>
}
function HostTable({hosts,onOpen}:{hosts:Host[];onOpen:(id:string)=>void}){return <div className="table-wrap"><table><thead><tr><th>Host</th><th>Status</th><th>Health</th><th>CPU</th><th>Memory</th><th>Incidents</th><th>Last report</th></tr></thead><tbody>{hosts.map(host=><tr key={host.id} onClick={()=>onOpen(host.id)} className="click-row"><td><strong>{host.hostname}</strong><small>{host.distribution} · {host.id}</small></td><td><span className={host.online?'status online':'status offline'}><i/>{host.online?'Online':'Offline'}</span></td><td><span className={host.health_score<60?'incident-count':'health-value'}>{host.health_score}/100</span></td><td><Progress value={host.cpu_usage_percent}/></td><td><Progress value={host.memory_usage_percent}/></td><td><span className={host.open_incidents?'incident-count':'muted'}>{host.open_incidents}</span></td><td className="muted">{ago(host.last_seen)}</td></tr>)}</tbody></table>{hosts.length===0&&<Empty text="No agent reports received yet."/>}</div>}
type FleetMetricSection = 'cpu'|'memory'|'disk'|'processes'|'services'
function FleetMetricsView({section,onOpenHost}:{section:FleetMetricSection;onOpenHost:(id:string)=>void}){
  const [hosts,setHosts]=useState<Host[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('')
  useEffect(()=>{let active=true;setLoading(true);setError('');void fetchAllHosts('',true).then(items=>{if(active)setHosts(items)}).catch(e=>{if(active)setError(e instanceof Error?e.message:'Metric snapshots could not be loaded')}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[section])
  const reported=hosts.filter(host=>host.report)
  if(loading)return <section className="panel"><Empty text="Loading latest host snapshots…"/></section>
  if(error)return <div className="error-banner"><strong>Metrics unavailable</strong><span>{error}</span></div>
  if(section==='cpu')return <>
    <section className="cards"><Metric title="Reporting hosts" value={reported.length} note="Have a current CPU snapshot" tone="blue"/><Metric title="Fleet average" value={reported.length?reported.reduce((sum,h)=>sum+(h.report?.cpu.usage_percent??0),0)/reported.length:0} note="CPU utilization percent" tone="teal"/><Metric title="Above 80%" value={reported.filter(h=>(h.report?.cpu.usage_percent??0)>=80).length} note="Current snapshots" tone="red"/></section>
    <section className="panel"><div className="panel-heading"><div><h2>CPU by host</h2><p>Latest agent snapshots. Select a host for per-core and historical charts.</p></div></div><div className="table-wrap"><table><thead><tr><th>Host</th><th>Utilization</th><th>Load 1m</th><th>Cores reported</th><th>Collected</th></tr></thead><tbody>{reported.map(host=><tr key={host.id} className="click-row" onClick={()=>onOpenHost(host.id)}><td><strong>{host.hostname}</strong><small>{host.id}</small></td><td><Progress value={host.report!.cpu.usage_percent}/></td><td>{host.report!.cpu.load_1.toFixed(2)}</td><td>{host.report!.cpu.core_usage_percent.length}</td><td>{ago(host.report!.collected_at)}</td></tr>)}</tbody></table>{reported.length===0&&<Empty text="No CPU snapshots have been received."/>}</div></section>
  </>
  if(section==='memory')return <>
    <section className="cards"><Metric title="Reporting hosts" value={reported.length} note="Have a current memory snapshot" tone="blue"/><Metric title="Fleet average" value={reported.length?reported.reduce((sum,h)=>sum+(h.report?.memory.usage_percent??0),0)/reported.length:0} note="RAM utilization percent" tone="purple"/><Metric title="Above 80%" value={reported.filter(h=>(h.report?.memory.usage_percent??0)>=80).length} note="Current snapshots" tone="red"/></section>
    <section className="panel"><div className="panel-heading"><div><h2>Memory by host</h2><p>Used, available, and memory pressure from the latest reports.</p></div></div><div className="table-wrap"><table><thead><tr><th>Host</th><th>Usage</th><th>Used</th><th>Available</th><th>Pressure avg10</th><th>Collected</th></tr></thead><tbody>{reported.map(host=><tr key={host.id} className="click-row" onClick={()=>onOpenHost(host.id)}><td><strong>{host.hostname}</strong><small>{host.id}</small></td><td><Progress value={host.report!.memory.usage_percent}/></td><td>{bytes(host.report!.memory.used_bytes)}</td><td>{bytes(host.report!.memory.available_bytes)}</td><td>{host.report!.memory.memory_pressure_avg10?.toFixed(2)??'n/a'}</td><td>{ago(host.report!.collected_at)}</td></tr>)}</tbody></table>{reported.length===0&&<Empty text="No memory snapshots have been received."/>}</div></section>
  </>
  if(section==='disk'){
    const disks=reported.flatMap(host=>(host.report?.disks??[]).map(disk=>({host,disk})))
    return <>
      <section className="cards"><Metric title="Reporting hosts" value={reported.length} note="Have a disk snapshot" tone="blue"/><Metric title="Filesystems" value={disks.length} note="Across received reports" tone="teal"/><Metric title="At least 80% full" value={disks.filter(({disk})=>disk.usage_percent>=80).length} note="Read-only recommendations only" tone="red"/></section>
      <section className="panel"><div className="panel-heading"><div><h2>Filesystem capacity</h2><p>Capacity, inode use, and read-only state by host and mount point.</p></div></div><div className="table-wrap"><table><thead><tr><th>Host</th><th>Mount</th><th>Device / filesystem</th><th>Usage</th><th>Inodes</th><th>Free</th><th>State</th></tr></thead><tbody>{disks.map(({host,disk})=><tr key={`${host.id}:${disk.mountpoint}`} className="click-row" onClick={()=>onOpenHost(host.id)}><td><strong>{host.hostname}</strong><small>{host.id}</small></td><td>{disk.mountpoint}</td><td>{disk.device} · {disk.filesystem}</td><td><Progress value={disk.usage_percent}/></td><td>{disk.inodes_usage_percent?.toFixed(1)??'n/a'}%</td><td>{bytes(disk.free_bytes)}</td><td className={disk.read_only?'incident-count':'health-value'}>{disk.read_only?'Read only':'Writable'}</td></tr>)}</tbody></table>{disks.length===0&&<Empty text="No filesystem snapshots have been received."/>}</div></section>
    </>
  }
  if(section==='processes'){
    const processes=reported.flatMap(host=>(host.report?.processes??[]).map(process=>({host,process}))).sort((a,b)=>b.process.cpu_percent-a.process.cpu_percent).slice(0,200)
    return <section className="panel"><div className="panel-heading"><div><h2>Top reported processes</h2><p>Agents report a bounded process sample. CPU, RSS, thread count, state, and uptime are real host data.</p></div></div><div className="table-wrap"><table><thead><tr><th>Host</th><th>PID</th><th>Process</th><th>CPU</th><th>Resident memory</th><th>Threads</th><th>Status</th><th>Uptime</th></tr></thead><tbody>{processes.map(({host,process})=><tr key={`${host.id}:${process.pid}`} className="click-row" onClick={()=>onOpenHost(host.id)}><td><strong>{host.hostname}</strong><small>{host.id}</small></td><td>{process.pid}</td><td>{process.name}</td><td>{process.cpu_percent.toFixed(1)}%</td><td>{bytes(process.memory_bytes)}</td><td>{process.threads}</td><td>{process.status}</td><td>{Math.floor(process.uptime_seconds/3600)}h</td></tr>)}</tbody></table>{processes.length===0&&<Empty text="No process snapshots have been received."/>}</div></section>
  }
  const services=reported.flatMap(host=>(host.report?.services??[]).map(service=>({host,service})))
  return <section className="panel"><div className="panel-heading"><div><h2>Configured systemd units</h2><p>Agents report only the units explicitly configured for monitoring.</p></div></div><div className="table-wrap"><table><thead><tr><th>Host</th><th>Service</th><th>State</th><th>Substate</th><th>Main PID</th><th>Last result</th><th>Restarts</th><th>Active since</th></tr></thead><tbody>{services.map(({host,service})=><tr key={`${host.id}:${service.name}`} className="click-row" onClick={()=>onOpenHost(host.id)}><td><strong>{host.hostname}</strong><small>{host.id}</small></td><td>{service.name}</td><td className={service.active_state==='active'?'health-value':'incident-count'}>{service.active_state}</td><td>{service.sub_state}</td><td>{service.main_pid}</td><td>{service.last_result??'unknown'}</td><td>{service.restart_count??0}</td><td>{service.since?ago(service.since):'unknown'}</td></tr>)}</tbody></table>{services.length===0&&<Empty text="No configured systemd services have been received."/>}</div></section>
}
function IncidentPage({status,onChange,canChange}:{status:'active'|'resolved';onChange:(id:number,status:string)=>Promise<void>;canChange:boolean}){
  const [items,setItems]=useState<Incident[]>([]);const [offset,setOffset]=useState(0);const [revision,setRevision]=useState(0);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const limit=100
  useEffect(()=>{let active=true;setLoading(true);setError('');void api<{items:Incident[]}>(`/api/v1/incidents?status=${status}&limit=${limit}&offset=${offset}`).then(result=>{if(active)setItems(result.items)}).catch(e=>{if(active)setError(e instanceof Error?e.message:'Incidents could not be loaded')}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[status,offset,revision])
  const update=async(id:number,next:string)=>{await onChange(id,next);setRevision(value=>value+1)}
  return <section className="panel"><div className="panel-heading"><div><h2>{status==='active'?'Active incidents':'Incident history'}</h2><p>{status==='active'?'Unresolved incidents, deduplicated by host and condition.':'Resolved incidents and their latest occurrence.'}</p></div><span className="muted">Showing {items.length?offset+1:0}–{offset+items.length}</span></div>{error&&<div className="error-banner">{error}</div>}{loading?<Empty text="Loading incidents…"/>:<IncidentList incidents={items} onChange={update} canChange={canChange}/>}<div className="pagination"><button className="small-button" disabled={offset===0||loading} onClick={()=>setOffset(Math.max(0,offset-limit))}>← Newer</button><span className="muted">Page {Math.floor(offset/limit)+1}</span><button className="small-button" disabled={loading||items.length<limit} onClick={()=>setOffset(offset+limit)}>Older →</button></div></section>
}
function Progress({value}:{value:number}){return <div className="progress-cell"><div className="progress"><span style={{width:`${Math.max(0,Math.min(100,value))}%`}}/></div><small>{value.toFixed(1)}%</small></div>}
function IncidentList({incidents,onChange,canChange=false}:{incidents:Incident[];onChange:(id:number,status:string)=>void;canChange?:boolean}){return <div className="list">{incidents.map(i=><div className="list-row" key={i.id}><div className={`severity ${i.severity}`}/><div className="list-content"><strong>{i.description}</strong><small>{i.host_id} · {ago(i.last_seen)} · {i.status}</small></div>{canChange&&i.status==='open'&&<button className="small-button" onClick={()=>onChange(i.id,'acknowledged')}>Acknowledge</button>}</div>)}{incidents.length===0&&<Empty text="No incidents reported."/>}</div>}
function RecoveryList({items}:{items:Recovery[]}){return <div className="list">{items.map(r=><div className="list-row" key={r.id}><div className={`recovery-icon ${r.verified?'verified':'failed'}`}>{r.verified?'✓':'!'}</div><div className="list-content"><strong>{r.policy} <span className="muted">· {r.service}</span></strong><small>{r.host_id} · {ago(r.started_at)}</small></div><span className={r.verified?'pill success':'pill warning'}>{r.outcome}</span></div>)}{items.length===0&&<Empty text="No recovery actions reported."/>}</div>}
type TimelineEvent={id:number;incident_id:number;event_type:string;actor:string;details:Record<string,string>;created_at:string}
type RechartsModule=typeof import('recharts')
function HistoryChart({title,unit,series,charts}:{title:string;unit:string;series:HistorySeries[];charts:RechartsModule}){
  const {CartesianGrid,Legend,Line,LineChart,ResponsiveContainer,Tooltip,XAxis,YAxis}=charts
  const rows=new Map<number,Record<string,number>>()
  for(const item of series){for(const point of item.points){const timestamp=point.timestamp*1000;const row=rows.get(timestamp)??{timestamp};row[item.name]=point.value;rows.set(timestamp,row)}}
  const data=Array.from(rows.values()).sort((a,b)=>a.timestamp-b.timestamp)
  const colors=['#5a9cf8','#4cc9a7','#bb91f2','#f2ac5c','#ed7185','#55c6d4']
  return <section className="panel"><div className="panel-heading"><div><h2>{title}</h2><p>Prometheus samples</p></div></div>{data.length===0?<Empty text="No historical samples yet."/>:<div className="chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={data}><CartesianGrid strokeDasharray="3 3" stroke="#263343"/><XAxis dataKey="timestamp" type="number" domain={['dataMin','dataMax']} tickFormatter={value=>new Date(Number(value)).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})} stroke="#8b9aab"/><YAxis unit={unit} stroke="#8b9aab"/><Tooltip labelFormatter={value=>new Date(Number(value)).toLocaleString()} formatter={value=>[`${Number(value).toFixed(1)} ${unit}`]}/><Legend/>{series.map((item,index)=><Line key={item.name} type="monotone" dataKey={item.name} name={item.name} stroke={colors[index%colors.length]} dot={false} isAnimationActive={false}/>)}</LineChart></ResponsiveContainer></div>}</section>
}
function HostDetails({host,onBack}:{host:Host;onBack:()=>void}){const report=host.report;const [timeline,setTimeline]=useState<TimelineEvent[]>([]);const [history,setHistory]=useState<Record<string,HistorySeries[]>>({});const [historyError,setHistoryError]=useState('');const [charts,setCharts]=useState<RechartsModule|null>(null);useEffect(()=>{let active=true;void import('recharts').then(module=>{if(active)setCharts(module)});return()=>{active=false}},[]);useEffect(()=>{let active=true;void api<{items:Incident[]}>('/api/v1/incidents?host_id='+encodeURIComponent(host.id)+'&limit=50').then(async result=>{const pages=await Promise.all(result.items.slice(0,15).map(i=>api<{items:TimelineEvent[]}>(`/api/v1/incidents/${i.id}/events`)));if(active)setTimeline(pages.flatMap(p=>p.items).sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at)).slice(0,30))}).catch(()=>undefined);return()=>{active=false}},[host.id]);useEffect(()=>{let active=true;const metrics=['cpu','memory','disk','network'];setHistoryError('');void Promise.all(metrics.map(async metric=>[metric,await api<{series:HistorySeries[]}>(`/api/v1/hosts/${encodeURIComponent(host.id)}/metrics?metric=${metric}&range=6h`)] as const)).then(results=>{if(active)setHistory(Object.fromEntries(results.map(([metric,data])=>[metric,data.series])))}).catch(e=>{if(active)setHistoryError(e instanceof Error?e.message:'Prometheus history could not be loaded')});return()=>{active=false}},[host.id]);if(!report)return <section className="panel"><button className="text-button" onClick={onBack}>← Back to hosts</button><Empty text="This host has no report."/></section>;if(!charts)return <section className="panel"><button className="text-button" onClick={onBack}>← Back to hosts</button><Empty text="Loading host charts…"/></section>;const {Bar,BarChart,CartesianGrid,ResponsiveContainer,Tooltip,XAxis,YAxis}=charts;return <>
  <button className="text-button back" onClick={onBack}>← Back to all hosts</button><section className="cards detail-cards"><Metric title="Health score" value={host.health_score} note="CPU 20 · RAM 20 · disk 20 · services 25 · network 10 · agent 5" tone="teal"/><Metric title="CPU usage" value={report.cpu.usage_percent} note={`Load average ${report.cpu.load_1.toFixed(2)}`} tone="blue"/><Metric title="Memory usage" value={report.memory.usage_percent} note={`${bytes(report.memory.used_bytes)} of ${bytes(report.memory.total_bytes)} · PSI avg10 ${report.memory.memory_pressure_avg10?.toFixed(2)??'n/a'}`} tone="purple"/><Metric title="Filesystems" value={report.disks.length} note={`${report.disks.filter(d=>d.usage_percent>=90).length} at 90% or more`} tone="teal"/><Metric title="Running services" value={report.services.filter(s=>s.active_state==='active').length} note={`${report.services.length} monitored`} tone="green"/></section>
  <section className="panel"><div className="panel-heading"><div><h2>CPU by core</h2><p>Snapshot collected {new Date(report.collected_at).toLocaleString()}</p></div><span className={host.online?'status online':'status offline'}><i/>{host.online?'Online':'Offline'}</span></div><div className="chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={report.cpu.core_usage_percent.map((usage,index)=>({core:`Core ${index}`,usage}))}><CartesianGrid strokeDasharray="3 3" stroke="#263343"/><XAxis dataKey="core" stroke="#8b9aab"/><YAxis domain={[0,100]} stroke="#8b9aab"/><Tooltip contentStyle={{background:'#17222f',border:'1px solid #314153',borderRadius:8}}/><Bar dataKey="usage" fill="#5a9cf8" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div></section>
  {historyError&&<div className="error-banner"><strong>Historical metrics unavailable</strong><span>{historyError}</span></div>}
  <div className="two-col"><HistoryChart title="CPU utilization · 6 hours" unit="%" series={history.cpu??[]} charts={charts}/><HistoryChart title="Memory utilization · 6 hours" unit="%" series={history.memory??[]} charts={charts}/><HistoryChart title="Filesystem utilization · 6 hours" unit="%" series={history.disk??[]} charts={charts}/><HistoryChart title="Network throughput · 6 hours" unit="B/s" series={history.network??[]} charts={charts}/></div>
  <div className="two-col"><section className="panel"><div className="panel-heading"><div><h2>Filesystems</h2><p>Capacity by mount point and inode consumption</p></div></div>{report.disks.map(d=><div className="disk-row" key={d.mountpoint}><div><strong>{d.mountpoint}</strong><small>{d.filesystem}{d.read_only?' · read-only':''} · {bytes(d.used_bytes)} / {bytes(d.total_bytes)} · {(d.inodes_usage_percent??0).toFixed(1)}% inodes</small></div><Progress value={d.usage_percent}/></div>)}</section><section className="panel"><div className="panel-heading"><div><h2>systemd services</h2><p>Configured units only</p></div></div>{(report.services??[]).map(s=><div className="service-row" key={s.name}><span className={s.active_state==='active'?'service-ok':'service-bad'}/><div><strong>{s.name}</strong><small>{s.active_state}/{s.sub_state} · PID {s.main_pid} · {s.last_result??'no result'} · restarts {s.restart_count??0}</small></div></div>)}{(report.services??[]).length===0&&<Empty text="No services configured for monitoring."/>}</section></div>
  <div className="two-col"><section className="panel"><div className="panel-heading"><div><h2>Network interfaces</h2><p>Link state and current throughput</p></div></div>{(report.interfaces??[]).map(n=>{const counters=(report.network??[]).find(x=>x.name===n.name);return <div className="network-row" key={n.name}><span className={n.up?'service-ok':'service-bad'}/><div><strong>{n.name}</strong><small>{n.up?'up':'down'} · MTU {n.mtu} · RX {bytes(counters?.rx_bytes_per_second??0)}/s · TX {bytes(counters?.tx_bytes_per_second??0)}/s · errors {(counters?.rx_errors??0)+(counters?.tx_errors??0)} · drops {(counters?.rx_drops??0)+(counters?.tx_drops??0)}</small></div></div>})}{(report.interfaces??[]).length===0&&<Empty text="No network interfaces reported."/>}</section><section className="panel"><div className="panel-heading"><div><h2>Disk I/O counters</h2><p>Cumulative counters since boot</p></div></div>{(report.disk_io??[]).map(d=><div className="disk-row" key={d.device}><div><strong>{d.device}</strong><small>Read {bytes(d.read_bytes)} · Write {bytes(d.write_bytes)} · {d.read_count+d.write_count} operations</small></div></div>)}{(report.disk_io??[]).length===0&&<Empty text="No disk I/O counters reported."/>}</section></div>
  <div className="two-col"><section className="panel"><div className="panel-heading"><div><h2>Top processes</h2><p>By reported CPU and resident memory</p></div></div>{report.processes.slice(0,8).map(p=><div className="process-row" key={p.pid}><span className="pid">{p.pid}</span><div><strong>{p.name}</strong><small>{p.status} · {p.threads} threads · up {Math.floor(p.uptime_seconds/3600)}h</small></div><span>{p.cpu_percent.toFixed(1)}% CPU</span><span>{bytes(p.memory_bytes)}</span></div>)}</section><section className="panel"><div className="panel-heading"><div><h2>Collection warnings</h2><p>Access limits or unavailable interfaces</p></div></div>{report.warnings.map((w,i)=><div className="warning-row" key={i}>{w}</div>)}{report.warnings.length===0&&<Empty text="No collection warnings."/>}</section></div>
  <section className="panel"><div className="panel-heading"><div><h2>Diagnostic recommendations</h2><p>Read-only suggestions; HostSentry never deletes files or terminates processes.</p></div></div>{(report.recommendations??[]).map((item,i)=><div className="warning-row" key={i}><strong>{item.target}</strong> · {item.message}</div>)}{(report.recommendations??[]).length===0&&<Empty text="No diagnostic recommendations for this snapshot."/>}</section>
  <section className="panel"><div className="panel-heading"><div><h2>Incident timeline</h2><p>Detection, status changes, and resolution events for this host</p></div></div><div className="list">{timeline.map(event=><div className="list-row" key={event.id}><div className="severity"/><div className="list-content"><strong>{event.event_type==='opened'?event.details.description??'Incident opened':event.event_type==='resolved'?'Incident resolved':`Status changed: ${event.details.from??'unknown'} → ${event.details.to??'unknown'}`}</strong><small>Incident #{event.incident_id} · {event.actor} · {new Date(event.created_at).toLocaleString()}</small></div></div>)}{timeline.length===0&&<Empty text="No incident events recorded for this host."/>}</div></section>
  <section className="panel system-info"><div><span>Distribution</span><strong>{report.system.distribution}</strong></div><div><span>Kernel</span><strong>{report.system.kernel_version}</strong></div><div><span>Agent</span><strong>{report.system.agent_version}</strong></div><div><span>Policy version</span><strong>{host.policy_version??report.policy_version??0}</strong></div><div><span>Uptime</span><strong>{Math.floor(report.system.uptime_seconds/86400)} days</strong></div></section>
  </>}
function PoliciesView({policies,hosts,recoveryEnabled,dryRun,refresh,readOnly}:{policies:Policy[];hosts:Host[];recoveryEnabled:boolean;dryRun:boolean;refresh:()=>Promise<void>;readOnly:boolean}){
  const [name,setName]=useState('');const [service,setService]=useState('');const [hostIDs,setHostIDs]=useState<string[]>([]);const [requireApproval,setRequireApproval]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  const create=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();setBusy(true);setError('');try{await api('/api/v1/policies',{method:'POST',body:JSON.stringify({name,action_type:'restart_service',service,failure_for:'30s',max_attempts:3,cooldown:'5m',verification_timeout:'30s',require_approval:requireApproval,enabled:false,host_ids:hostIDs})});setName('');setService('');setHostIDs([]);setRequireApproval(true);await refresh()}catch(e){setError(e instanceof Error?e.message:'Policy could not be saved')}finally{setBusy(false)}}
  const setEnabled=async(policy:Policy,enabled:boolean)=>{setBusy(true);setError('');try{await api(`/api/v1/policies/${policy.id}`,{method:'PUT',body:JSON.stringify({...policy,enabled})});await refresh()}catch(e){setError(e instanceof Error?e.message:'Policy could not be updated')}finally{setBusy(false)}}
  const disable=async(policy:Policy)=>{setBusy(true);setError('');try{await api(`/api/v1/policies/${policy.id}`,{method:'DELETE'});await refresh()}catch(e){setError(e instanceof Error?e.message:'Policy could not be disabled')}finally{setBusy(false)}}
  return <>
    <section className="policy-state"><div><strong>Central recovery {recoveryEnabled?'enabled':'disabled'}</strong><span>{dryRun?'Dry-run is enforced by the central server':'Live actions require local opt-in and systemd permission'}</span></div><span className={recoveryEnabled?'pill warning':'pill success'}>{recoveryEnabled?(dryRun?'DRY RUN':'ENABLED'):'DISABLED'}</span></section>
    {error&&<div className="error-banner"><strong>Policy update failed</strong><span>{error}</span></div>}
    {!readOnly&&<section className="panel"><div className="panel-heading"><div><h2>Create recovery policy</h2><p>Only allowlisted service restarts are supported. New policies start disabled.</p></div></div><form className="policy-form" onSubmit={create}><label>Policy name<input required maxLength={128} pattern="[A-Za-z0-9_-]+" value={name} onChange={e=>setName(e.target.value)} placeholder="web-service-recovery"/></label><label>systemd service<input required value={service} onChange={e=>setService(e.target.value)} placeholder="nginx.service" pattern="[A-Za-z0-9_.:@-]+\.service"/></label><label>Assigned hosts<select multiple required value={hostIDs} onChange={e=>setHostIDs(Array.from(e.target.selectedOptions).map(o=>o.value))}>{hosts.map(h=><option key={h.id} value={h.id}>{h.hostname} · {h.id}</option>)}</select><small>Hold Ctrl or ⌘ to select several hosts.</small></label><div className="policy-defaults"><span>Trigger after <b>30s</b> failed</span><span>Max attempts <b>3</b></span><span>Cooldown <b>5m</b></span><span>Verify within <b>30s</b></span></div><label className="check-label"><input type="checkbox" checked={requireApproval} onChange={e=>setRequireApproval(e.target.checked)}/> Require approval (agent will not restart while enabled)</label><button className="refresh" disabled={busy||!hosts.length}>Create disabled policy</button></form></section>}
    <section className="panel"><div className="panel-heading"><div><h2>Configured policies</h2><p>Service names must also be allowlisted on each agent</p></div></div><div className="policy-list">{policies.map(p=><article className="policy-card" key={p.id}><div className="policy-heading"><div><strong>{p.name}</strong><span>{p.service} · {p.host_ids.length} host(s)</span></div><span className={p.enabled?'pill warning':'pill success'}>{p.enabled?'ENABLED':'DISABLED'}</span></div><div className="policy-meta"><span>Failure {p.failure_for}</span><span>Attempts {p.max_attempts}</span><span>Cooldown {p.cooldown}</span><span>Approval {p.require_approval?'required':'not required'}</span><span>Verify {p.verification_timeout}</span></div><div className="policy-hosts">{p.host_ids.map(id=><span key={id}>{id}</span>)}</div>{!readOnly&&<div className="policy-actions"><button className="small-button" disabled={busy} onClick={()=>void setEnabled(p,!p.enabled)}>{p.enabled?'Disable':'Enable'}</button><button className="small-button danger-button" disabled={busy||!p.enabled} onClick={()=>void disable(p)}>Retire</button></div>}</article>)}{policies.length===0&&<Empty text="No centrally assigned policies."/>}</div></section>
  </>
}
function GroupsView({groups,hosts,refresh,onOpen,readOnly}:{groups:Group[];hosts:Host[];refresh:()=>Promise<void>;onOpen:(group:Group)=>void;readOnly:boolean}){
  const [name,setName]=useState('');const [hostIDs,setHostIDs]=useState<string[]>([]);const [error,setError]=useState('');const [busy,setBusy]=useState(false)
  const create=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();setBusy(true);setError('');try{await api('/api/v1/groups',{method:'POST',body:JSON.stringify({name,host_ids:hostIDs})});setName('');setHostIDs([]);await refresh()}catch(e){setError(e instanceof Error?e.message:'Group could not be saved')}finally{setBusy(false)}}
  const remove=async(group:Group)=>{setBusy(true);setError('');try{await api(`/api/v1/groups/${group.id}`,{method:'DELETE'});await refresh()}catch(e){setError(e instanceof Error?e.message:'Group could not be deleted')}finally{setBusy(false)}}
  return <>
    {error&&<div className="error-banner"><strong>Group update failed</strong><span>{error}</span></div>}
    {!readOnly&&<section className="panel"><div className="panel-heading"><div><h2>Create host group</h2><p>Groups organize hosts for operations and policy assignment.</p></div></div><form className="policy-form" onSubmit={create}><label>Group name<input required maxLength={80} pattern="[A-Za-z0-9][A-Za-z0-9 _.-]*" value={name} onChange={e=>setName(e.target.value)} placeholder="web tier"/></label><label>Members<select multiple value={hostIDs} onChange={e=>setHostIDs(Array.from(e.target.selectedOptions).map(o=>o.value))}>{hosts.map(h=><option key={h.id} value={h.id}>{h.hostname} · {h.id}</option>)}</select><small>Host membership can be empty and changed through the API.</small></label><button className="refresh" disabled={busy}>Create group</button></form></section>}
    <section className="group-grid">{groups.map(group=><article className="panel group-card" key={group.id}><div className="panel-heading"><div><h2>{group.name}</h2><p>{group.host_count} host(s)</p></div>{!readOnly&&<button className="small-button danger-button" disabled={busy} onClick={()=>void remove(group)}>Delete</button>}</div><div className="policy-hosts">{group.host_ids.map(id=><span key={id}>{id}</span>)}</div><div className="group-actions"><button className="text-button" onClick={()=>onOpen(group)}>View hosts →</button></div></article>)}{groups.length===0&&<section className="panel"><Empty text="No host groups created."/></section>}</section>
  </>
}
type Notification = {id:number;host_id:string;severity:string;message:string;status:string;created_at:string;updated_at:string}
function NotificationsView(){
  const [items,setItems]=useState<Notification[]>([]);const [error,setError]=useState('')
  useEffect(()=>{let active=true;void api<{items:Notification[]}>('/api/v1/notifications?limit=100').then(data=>{if(active)setItems(data.items)}).catch(e=>{if(active)setError(e instanceof Error?e.message:'Notifications could not be loaded')});return()=>{active=false}},[])
  return <section className="panel"><div className="panel-heading"><div><h2>Incident notifications</h2><p>Notifications are derived from recorded incidents and refresh on page load.</p></div></div>{error&&<div className="error-banner">{error}</div>}<IncidentList incidents={items.map(n=>({id:n.id,host_id:n.host_id,severity:n.severity,description:n.message,status:n.status,first_seen:n.created_at,last_seen:n.updated_at,type:'incident'}))} onChange={()=>{}} /></section>
}
function ReportsView(){const [error,setError]=useState('');const download=async()=>{setError('');try{const token=sessionStorage.getItem('hostsentry-session');const response=await fetch('/api/v1/reports/hosts.csv',{headers:token?{Authorization:`Bearer ${token}`}:{}});if(!response.ok)throw new Error(`Report download failed (${response.status})`);const url=URL.createObjectURL(await response.blob());const anchor=document.createElement('a');anchor.href=url;anchor.download='hostsentry-hosts.csv';anchor.click();URL.revokeObjectURL(url)}catch(e){setError(e instanceof Error?e.message:'Report download failed')}};return <section className="panel"><div className="panel-heading"><div><h2>Fleet reports</h2><p>Export a current inventory and health snapshot from the central database.</p></div></div><div className="report-actions"><button className="refresh" onClick={()=>void download()}>Download host inventory CSV</button>{error&&<p>{error}</p>}<p>Includes host identity, distribution, kernel, agent version, online state, latest CPU and memory usage, and active incident count. Timestamps are UTC.</p></div></section>}
type Settings = {health_weights:Record<string,number>;recovery_enabled:boolean;recovery_dry_run:boolean;anomaly_detection_enabled:boolean;anomaly_minimum_samples:number;anomaly_sigma:number;agent_offline_after_seconds:number;policy_action_types:string[];notification_channels:string[]}
function SettingsView(){
  const [settings,setSettings]=useState<Settings|null>(null);const [error,setError]=useState('')
  useEffect(()=>{let active=true;void api<Settings>('/api/v1/settings').then(data=>{if(active)setSettings(data)}).catch(e=>{if(active)setError(e instanceof Error?e.message:'Settings could not be loaded')});return()=>{active=false}},[])
  return <><section className="panel"><div className="panel-heading"><div><h2>Central server settings</h2><p>Read-only runtime configuration. Change environment settings on the server and restart the backend.</p></div></div>{error&&<div className="error-banner">{error}</div>}{settings&&<div className="settings-grid"><div><span>Recovery</span><strong>{settings.recovery_enabled?'Enabled':'Disabled'} · {settings.recovery_dry_run?'dry-run':'live mode'}</strong></div><div><span>Anomaly detection</span><strong>{settings.anomaly_detection_enabled?'Enabled':'Disabled'} · minimum {settings.anomaly_minimum_samples} samples · {settings.anomaly_sigma}σ</strong></div><div><span>Agent offline threshold</span><strong>{settings.agent_offline_after_seconds} seconds</strong></div><div><span>Recovery actions allowed</span><strong>{settings.policy_action_types.join(', ')}</strong></div><div><span>Health score weights</span><strong>{Object.entries(settings.health_weights).map(([key,value])=>`${key} ${value}%`).join(' · ')}</strong></div><div><span>External notifications</span><strong>{settings.notification_channels.length?settings.notification_channels.join(', '):'Not configured'}</strong></div></div>}</section><UserManagement/></>
}
type UserAccount={id:string;email:string;display_name:string;role:string;disabled:boolean;created_at:string}
function UserManagement(){
  const [current,setCurrent]=useState<UserAccount|null>(null);const [users,setUsers]=useState<UserAccount[]>([]);const [email,setEmail]=useState('');const [name,setName]=useState('');const [password,setPassword]=useState('');const [role,setRole]=useState('viewer');const [error,setError]=useState('');const [busy,setBusy]=useState(false)
  const load=useCallback(async()=>{try{const me=await api<UserAccount>('/api/v1/auth/me');setCurrent(me);if(me.role==='admin'){const data=await api<{items:UserAccount[]}>('/api/v1/users');setUsers(data.items)}}catch(e){setError(e instanceof Error?e.message:'User management unavailable')}},[])
  useEffect(()=>{void load()},[load])
  const create=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();setBusy(true);setError('');try{await api('/api/v1/users',{method:'POST',body:JSON.stringify({email,display_name:name,password,role})});setEmail('');setName('');setPassword('');await load()}catch(e){setError(e instanceof Error?e.message:'User could not be created')}finally{setBusy(false)}}
  const update=async(user:UserAccount,patch:Partial<Pick<UserAccount,'role'|'disabled'>>)=>{setBusy(true);setError('');try{await api(`/api/v1/users/${user.id}`,{method:'PATCH',body:JSON.stringify(patch)});await load()}catch(e){setError(e instanceof Error?e.message:'User could not be updated')}finally{setBusy(false)}}
  if(current?.role!=='admin')return null
  return <section className="panel"><div className="panel-heading"><div><h2>User access</h2><p>Admins manage accounts. Operators can update incidents. Viewers have read-only access.</p></div></div>{error&&<div className="error-banner">{error}</div>}<form className="policy-form user-form" onSubmit={create}><label>Email<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Display name<input required maxLength={120} value={name} onChange={e=>setName(e.target.value)}/></label><label>Temporary password<input type="password" required minLength={14} maxLength={72} value={password} onChange={e=>setPassword(e.target.value)}/></label><label>Role<select value={role} onChange={e=>setRole(e.target.value)}><option value="viewer">Viewer</option><option value="operator">Operator</option><option value="admin">Admin</option></select></label><button className="refresh" disabled={busy}>Create user</button></form><div className="user-list">{users.map(user=><article key={user.id} className="user-row"><div><strong>{user.display_name}</strong><small>{user.email}{user.disabled?' · disabled':''}</small></div><select value={user.role} disabled={busy} onChange={e=>void update(user,{role:e.target.value})}><option value="viewer">Viewer</option><option value="operator">Operator</option><option value="admin">Admin</option></select><button className="small-button" disabled={busy||user.id===current.id} onClick={()=>void update(user,{disabled:!user.disabled})}>{user.disabled?'Enable':'Disable'}</button></article>)}</div></section>
}
function Empty({text}:{text:string}){return <div className="empty">{text}</div>}
